class Solution:
    def detectCapitalUse(self, word: str) -> bool:
        if not word:
            return True
        firstChar = word[0]
        if firstChar.isupper():
            for char in word[1:]:
                if char.islower():
                    return False
        else:
            for char in word[1:]:
                if char.isupper():
                    return False
